    $global:g.Ell($cx, ($by - 0.28 * $hh), $ww, (0.28 * $hh), $l[1])
  }
  $global:g.Ell($cx, ($by - 0.14 * $h), (0.2 * $w + 0.5), (0.14 * $h), $global:b3)
}

# Espejo de una lista plana de puntos respecto a un eje vertical (x -> axis*2 - x)
function Mir([double[]]$pts, [double]$axis) {
  $o = New-Object 'double[]' $pts.Length
  for ($n = 0; $n -lt $pts.Length; $n += 2) { $o[$n] = $axis * 2 - $pts[$n]; $o[$n + 1] = $pts[$n + 1] }
  return , $o
}

