function BrickTile([int]$bh, [bool]$stagger, $mortar, $tones, $hi, $lo, $nA, $nB, [int]$seed) {
  New-Canvas 64 64
  $bw = 32
  for ($y = 0; $y -lt 64; $y++) {
    for ($x = 0; $x -lt 64; $x++) {
      $row = [math]::Floor($y / $bh); $ry = $y % $bh
