      $xx = ($x + $off) % 64; $bx = $xx % $bw; $idx = [math]::Floor($xx / $bw)
      if ($ry -eq ($bh - 1) -or $bx -eq ($bw - 1)) { $col = $mortar }
      else {
        $col = $tones[($row * 2 + $idx) % $tones.Count]
        if (($ry -eq 0 -and $bx -gt 0) -or ($bx -eq 0 -and $ry -gt 0)) { $col = $hi }
        elseif ($ry -eq ($bh - 2) -or $bx -eq ($bw - 2)) { $col = $lo }
      }
      $global:g.Set($x, $y, $col)
    }
  }
  $n = 0
  foreach ($t in ($tones | Select-Object -Unique)) {
    $global:g.Noise($t, $nA, 7, $seed + $n); $global:g.Noise($t, $nB, 5, $seed + 50 + $n); $n++
  }
}

