# ---------- bola de fuego en vuelo (bucle), hacia la derecha. R = radio de la cabeza ----------
function FireballVfx([string]$name, [double]$R, [string]$desc) {
  $cw = [int][math]::Ceiling($R * 10); $ch = [int][math]::Ceiling($R * 4.4); if (($ch % 2) -eq 1) { $ch++ }
  $hx = [int][math]::Round($cw - $R * 1.8); $cy = [int]($ch / 2)
  New-Vfx $name $cw $ch 8 12 'bucle' $hx $cy $desc {
    param($f, $t)
    $ramp = $magFire; $ph = 2 * [math]::PI * $t; $NT = 10
    for ($i = $NT; $i -ge 1; $i--) {
      $tx = $hx - $R * 0.68 * $i; $ty = $cy + $R * 0.3 * [math]::Sin($ph + $i * 0.9) * (0.4 + $i / $NT)
      $tr = $R * (1 - $i / ($NT + 1.0)) + 0.5
      $m1 = 0; if ($i -ge 5) { $m1 = 1 }; if ($i -ge 8) { $m1 = 3 }
      $g.EllD($tx, $ty, $tr * 1.1 + 0.5, $tr * 0.95, $ramp[0], $m1)
      if ($i -le 8) { $m2 = 0; if ($i -ge 6) { $m2 = 1 }; $g.EllD($tx + $R * 0.05, $ty, $tr * 0.78, $tr * 0.66, $ramp[1], $m2) }
      if ($i -le 6) { $g.EllD($tx + $R * 0.1, $ty, $tr * 0.5, $tr * 0.42, $ramp[2], 0) }
    }
    $rng = New-Object System.Random($f * 11 + 5); $esz = [int][math]::Max(1, [math]::Round($R / 14))
    for ($k = 0; $k -lt (5 + [int]($R / 3)); $k++) {
      $ex = $hx - $R * (1.4 + $rng.NextDouble() * 7); $ey = $cy + ($rng.NextDouble() - 0.5) * $R * 2.3
      $ec = $ramp[3]; if (($k % 2) -eq 1) { $ec = $ramp[2] }
      Pt $ex $ey $esz $ec
    }
    $fb = $R * 1.15 * (1 + 0.03 * [math]::Sin($ph))
    foreach ($lb in @(@(1.0, $ramp[0]), @(0.78, $ramp[1]), @(0.55, $ramp[2]), @(0.32, $ramp[3]))) {
      $sc2 = $lb[0]
      $g.Ell($hx, $cy, $fb * 0.62 * $sc2, $fb * 0.62 * $sc2, $lb[1])
      for ($k = 0; $k -lt 7; $k++) {
        $la = $k * 2 * [math]::PI / 7 + 0.4
        $lr = $fb * (0.30 + 0.06 * [math]::Sin($ph + $k * 1.3)) * $sc2 + 0.5
        $g.Ell($hx + [math]::Cos($la) * $fb * 0.58 * $sc2, $cy + [math]::Sin($la) * $fb * 0.58 * $sc2, $lr, $lr, $lb[1])
      }
    }
    $g.Ell($hx - $fb * 0.1, $cy - $fb * 0.1, $fb * 0.16, $fb * 0.16, $ramp[4])
  }
}

