function ThickLine([double]$x1, [double]$y1, [double]$x2, [double]$y2, [double]$wd, $col) {
  $dx = $x2 - $x1; $dy = $y2 - $y1; $len = [math]::Sqrt($dx * $dx + $dy * $dy)
  if ($len -lt 0.01) { return }
  $nx = -$dy / $len; $ny = $dx / $len
