function BoltPts([double]$ax, [double]$ay, [double]$bx, [double]$by, [int]$n, [double]$a0, [double]$a1, $rng) {
  $dx = $bx - $ax; $dy = $by - $ay; $len = [math]::Sqrt($dx * $dx + $dy * $dy); $nx = -$dy / $len; $ny = $dx / $len
  $pts = @(); $sg = 1
