    $u = $i / [double]$n; $amp = $a0 + ($a1 - $a0) * $u; $off = 0
    if ($i -gt 0 -and $i -lt $n) { if ($rng.NextDouble() -lt 0.55) { $sg = -$sg }; $off = $sg * $amp * (0.2 + 0.8 * $rng.NextDouble()) }
    $pts += , @(($ax + $dx * $u + $nx * $off), ($ay + $dy * $u + $ny * $off))
  }
  return , $pts
}

function RefinePts($pts, [double]$amp, $rng) {
  $out = @()
  for ($i = 0; $i -lt $pts.Count - 1; $i++) {
    $ax = $pts[$i][0]; $ay = $pts[$i][1]; $bx = $pts[$i + 1][0]; $by = $pts[$i + 1][1]
    $dx = $bx - $ax; $dy = $by - $ay; $ln = [math]::Sqrt($dx * $dx + $dy * $dy); if ($ln -lt 0.01) { $ln = 1 }
    $o = ($rng.NextDouble() * 2 - 1) * $amp
